  @media(max-width:900px){#plv3 #samples .samp-grid{grid-template-columns:1fr;max-width:440px;margin-inline:auto}}
  #plv3 #samples .card2{background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);overflow:hidden;display:flex;flex-direction:column}
  #plv3 #samples .card2 .top{display:flex;align-items:center;gap:9px;padding:12px 14px;border-bottom:1px solid var(--border)}
