  #plv3 #samples .card2 .net{margin-inline-start:auto;font-size:11px;font-weight:800;padding:4px 10px;border-radius:999px}
  #plv3 #samples .net.ig{background:linear-gradient(135deg,#f0743a,#d6249f);color:#fff}
