  #plv3 #samples .adbar .dom{font-size:11px;color:var(--ink-muted)}
  #plv3 #samples .adbar .b{background:var(--brand);color:#160b28;font-weight:800;font-size:12.5px;padding:8px 14px;border-radius:8px}
  /* WhatsApp chat */
