  #plv3 #samples .bub{max-width:82%;padding:9px 12px;border-radius:14px;font-size:13px;line-height:1.55}
  #plv3 #samples .bub.inb{background:#1f2c26;color:#e9f3ee;align-self:flex-start;border-top-right-radius:4px}
  #plv3 #samples .bub.out{background:#25D366;color:#06130D;align-self:flex-end;border-top-left-radius:4px;font-weight:600}
  #plv3 #samples .lead{margin:2px 14px 14px;font-size:12px;font-weight:800;color:#25D366;text-align:center}
  #plv3 #samples .card2 .lbl{padding:11px 14px 0;font-size:12px;font-weight:800;color:var(--brand)}


          #plv3 #samples .vid .vidwrap{display:grid;grid-template-columns:1.5fr 1fr}
          @media(max-width:900px){#plv3 #samples .vid .vidwrap{grid-template-columns:1fr}}
          #plv3 #samples .vframe{position:relative;aspect-ratio:16/9;background:radial-gradient(120% 120% at 30% 20%,#2a2536,#141220);display:grid;place-items:center;overflow:hidden}
