  #plv3 .pc-layout{display:grid;grid-template-columns:200px 1fr;gap:28px;align-items:start;max-width:1000px;margin:0 auto}
  #plv3 .pc-side-desktop{position:sticky;top:100px;display:flex;flex-direction:column;gap:3px}
  #plv3 .pc-side-mobile{display:none}
  #plv3 .pc-side-item{text-align:right;padding:11px 14px;border:none;border-inline-end:2px solid transparent;background:transparent;color:var(--ink-muted);font-size:15px;font-weight:600;cursor:pointer;border-radius:8px 0 0 8px;transition:all .2s;font-family:inherit}
  #plv3 .pc-side-item:hover{background:color-mix(in srgb,var(--brand) 6%,transparent);color:var(--ink)}
  #plv3 .pc-side-item.active{background:color-mix(in srgb,var(--brand) 10%,transparent);color:var(--brand);border-inline-end-color:var(--brand);font-weight:700}
  #plv3 .pc-side-tag{display:block;font-size:11px;color:var(--ink-muted);margin-top:1px;font-weight:400;direction:ltr;text-align:right}
  #plv3 .pc-side-item.active .pc-side-tag{color:var(--brand);opacity:.7}
  #plv3 .pc-carousel-area{position:relative}
  #plv3 .pc-wrap{perspective:1200px;position:relative;height:580px;overflow:visible;cursor:pointer}
  #plv3 .pc-card{position:absolute;top:0;left:50%;width:340px;margin-left:-170px;border:1px solid color-mix(in srgb,var(--brand) 15%,transparent);
    border-radius:16px;padding:26px 22px;background:var(--surface);transition:all .6s cubic-bezier(.25,.8,.25,1);backface-visibility:hidden}
  #plv3 .pc-card.center{transform:translateX(0) translateZ(0) rotateY(0) scale(1);z-index:30;opacity:1;border-color:color-mix(in srgb,var(--brand) 42%,transparent);box-shadow:0 0 50px color-mix(in srgb,var(--brand) 16%,transparent);cursor:default}
  #plv3 .pc-card.right{transform:translateX(66%) translateZ(-150px) rotateY(-18deg) scale(.8);z-index:20;opacity:.8;filter:blur(.5px) brightness(.9);cursor:pointer}
  #plv3 .pc-card.left{transform:translateX(-66%) translateZ(-150px) rotateY(18deg) scale(.8);z-index:20;opacity:.8;filter:blur(.5px) brightness(.9);cursor:pointer}
  #plv3 .pc-card.far-right{transform:translateX(116%) translateZ(-300px) rotateY(-28deg) scale(.62);z-index:10;opacity:.4;filter:blur(2px) brightness(.82);cursor:pointer}
  #plv3 .pc-card.far-left{transform:translateX(-116%) translateZ(-300px) rotateY(28deg) scale(.62);z-index:10;opacity:.4;filter:blur(2px) brightness(.82);cursor:pointer}
  #plv3 .pc-card.hidden-card{transform:translateX(0) translateZ(-500px) scale(.4);z-index:1;opacity:0;pointer-events:none}
  #plv3 .pc-nav{display:flex;justify-content:center;gap:16px;margin-top:30px}
  #plv3 .pc-btn{width:44px;height:44px;border-radius:50%;border:1px solid color-mix(in srgb,var(--brand) 30%,transparent);background:color-mix(in srgb,var(--brand) 5%,transparent);color:var(--brand);font-size:20px;cursor:pointer;display:flex;align-items:center;justify-content:center;transition:all .2s}
  #plv3 .pc-btn:hover{background:color-mix(in srgb,var(--brand) 15%,transparent);border-color:var(--brand)}
  #plv3 .pc-dots{display:flex;justify-content:center;gap:8px;margin-top:16px}
  #plv3 .pc-dot{width:8px;height:8px;border-radius:50%;background:color-mix(in srgb,var(--brand) 22%,transparent);border:none;cursor:pointer;transition:all .3s;padding:0}
  #plv3 .pc-dot.active{background:var(--brand);width:24px;border-radius:4px}
  #plv3 .pc-popular{position:absolute;top:-12px;inset-inline-end:20px;background:var(--brand);color:#0c0a13;font-size:11px;font-weight:700;padding:4px 12px;border-radius:20px}
  #plv3 .pc-header{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:12px;gap:10px}
  #plv3 .pc-name{font-size:1.15rem;font-weight:700;color:var(--ink);font-family:'Rubik'}
  #plv3 .pc-price{font-size:1.6rem;font-weight:800;color:var(--brand);text-align:left;line-height:1.1;direction:ltr;font-family:'Rubik'}
  #plv3 .pc-price small{font-size:.9rem;font-weight:700}
  #plv3 .pc-price-note{font-size:.68rem;color:var(--ink-muted);text-align:left}
  #plv3 .pc-desc{font-size:.84rem;color:var(--ink-2);line-height:1.6;margin-bottom:14px}
  #plv3 .pc-target{font-size:.75rem;color:var(--ink-muted);font-style:italic;margin-bottom:14px;padding-bottom:14px;border-bottom:1px solid var(--border)}
  #plv3 .pc-items{list-style:none;margin-bottom:14px;padding:0}
  #plv3 .pc-items li{display:flex;align-items:flex-start;gap:8px;font-size:.84rem;color:var(--ink-2);padding:4px 0}
  #plv3 .pc-check{color:var(--brand);flex-shrink:0;font-weight:700}
  #plv3 .pc-benefits{display:flex;flex-wrap:wrap;gap:5px;margin-bottom:14px}
  #plv3 .pc-benefit{font-size:.68rem;color:color-mix(in srgb,var(--brand) 75%,white);background:color-mix(in srgb,var(--brand) 10%,transparent);padding:3px 8px;border-radius:12px}
  #plv3 .pc-cta{display:block;width:100%;padding:12px;background:var(--brand);color:#0c0a13;font-weight:700;font-size:.9rem;border:none;border-radius:10px;cursor:pointer;text-align:center;font-family:inherit}
  #plv3 .pc-cta:hover{background:var(--brand-hover)}
  #plv3 .pc-footnote{font-size:.72rem;color:var(--brand);font-style:italic;margin-top:10px;opacity:.85}
  @media(max-width:900px){
    #plv3 .pc-layout{grid-template-columns:1fr;gap:0}
    #plv3 .pc-side-desktop{display:none}
    #plv3 .pc-side-mobile{display:flex;gap:8px;overflow-x:auto;padding-bottom:12px;margin-bottom:8px;scrollbar-width:none}
    #plv3 .pc-side-mobile::-webkit-scrollbar{display:none}
    #plv3 .pc-tab{flex-shrink:0;padding:9px 15px;border-radius:999px;border:1px solid color-mix(in srgb,var(--brand) 20%,transparent);background:transparent;color:var(--ink-muted);font-size:.82rem;cursor:pointer;white-space:nowrap;font-family:inherit}
    #plv3 .pc-tab.active{background:color-mix(in srgb,var(--brand) 10%,transparent);color:var(--brand);border-color:var(--brand);font-weight:700}
  }
  @media(max-width:768px){
    #plv3 .pc-layout{display:block}
    #plv3 .pc-side-mobile,#plv3 .pc-side-desktop{display:none}
    #plv3 .pc-wrap{perspective:none;height:auto!important;overflow:visible;display:flex;flex-direction:column;gap:16px;cursor:default}
    #plv3 .pc-card{position:relative!important;top:auto;left:auto;width:100%;max-width:420px;margin:0 auto;padding:24px 20px;
      transform:none!important;opacity:1!important;filter:none!important;box-shadow:none!important;
      border-color:color-mix(in srgb,var(--brand) 18%,transparent)!important;cursor:default}
    #plv3 .pc-card.is-popular{border-color:color-mix(in srgb,var(--brand) 45%,transparent)!important;box-shadow:0 0 34px color-mix(in srgb,var(--brand) 12%,transparent)!important}
    #plv3 .pc-nav,#plv3 .pc-dots{display:none}
  }

