  const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  // mobile burger menu
  const header=document.querySelector('header'), burger=document.querySelector('.burger');
  burger.addEventListener('click',()=>{const open=header.classList.toggle('mobile-open');burger.setAttribute('aria-expanded',open)});
  document.querySelectorAll('.nav-links a').forEach(a=>a.addEventListener('click',()=>{header.classList.remove('mobile-open');burger.setAttribute('aria-expanded','false')}));

  // scroll reveal
  const io=new IntersectionObserver((es)=>{es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}})},{threshold:.12});
  document.querySelectorAll('.reveal').forEach(el=>io.observe(el));

  // dashboard: mock lift + bars grow
  const mock=document.getElementById('mock');
  new IntersectionObserver((es,o)=>{es.forEach(e=>{if(e.isIntersecting){
    mock.classList.add('in');
    document.querySelectorAll('#mbars .b').forEach((b,i)=>setTimeout(()=>b.style.height=b.dataset.h+'%', reduce?0:120+i*60));
    o.disconnect();
  }})},{threshold:.3}).observe(mock);

  // count-up
  function countUp(el){
    const target=parseFloat(el.dataset.count), dec=parseInt(el.dataset.dec||'0'), suf=el.dataset.suffix||'';
    if(reduce){el.textContent=target.toFixed(dec)+suf;return}
    const dur=1200, t0=performance.now();
    function tick(t){const p=Math.min((t-t0)/dur,1); const e=1-Math.pow(1-p,3);
      el.textContent=(target*e).toFixed(dec)+suf; if(p<1)requestAnimationFrame(tick);}
    requestAnimationFrame(tick);
  }
  document.querySelectorAll('[data-count]').forEach(el=>{
    new IntersectionObserver((es,o)=>{es.forEach(e=>{if(e.isIntersecting){countUp(el);o.disconnect()}})},{threshold:.6}).observe(el);
  });

  // autonomy switch
  const modes=[
    {t:'מצב יועץ',d:'הסוכנים מנתחים וממליצים, ואתם מבצעים. אפס פעולות אוטומטיות, שליטה מלאה.',s:'מומלץ בהתחלה, עד שבונים אמון'},
    {t:'מצב אישור',d:'הסוכנים מכינים הכל ומחכים לאישור שלך לפני כל פרסום או שינוי תקציב.',s:'האיזון בין שליטה למהירות'},
    {t:'טייס אוטומטי',d:'הסוכנים פועלים לבד תחת מגבלות שאתם קובעים: תקרת תקציב, ערוצים, וסוגי פעולות.',s:'למי שכבר סומך על הצוות'}
  ];
  const sw=document.querySelector('.switch'), glide=sw.querySelector('.glide'),
        btns=[...sw.querySelectorAll('button')], panel=document.getElementById('autopanel');
  function moveGlide(btn){glide.style.width=btn.offsetWidth+'px';glide.style.right=(btn.offsetParent.offsetWidth-btn.offsetLeft-btn.offsetWidth)+'px'}
  function setMode(i){btns.forEach(b=>b.classList.remove('active'));btns[i].classList.add('active');moveGlide(btns[i]);
    const m=modes[i];panel.innerHTML=`<h3>${m.t}</h3><p>${m.d}</p><span class="st">${m.s}</span>`}
  btns.forEach(b=>b.addEventListener('click',()=>setMode(parseInt(b.dataset.i))));
  window.addEventListener('load',()=>moveGlide(btns[0]));
  setTimeout(()=>moveGlide(btns[0]),300);

  // confetti on pricing select (brand colors, matches lib/confetti.ts)
  document.querySelectorAll('.buy').forEach(btn=>btn.addEventListener('click',(e)=>{
    e.preventDefault();
    if(typeof confetti==='function' && !reduce){
      const r=btn.getBoundingClientRect();
      confetti({particleCount:90,spread:75,
        origin:{x:(r.left+r.width/2)/window.innerWidth,y:(r.top+r.height/2)/window.innerHeight},
        colors:['#A78BFA','#C4B5FD','#8B5CF6','#E9E7EF'],disableForReducedMotion:true});
    }
  }));

  // interactive screen tabs (click a tab -> show that screen)
  const tabBtns=[...document.querySelectorAll('.tabs button')], tabImg=document.getElementById('tabimg'), tabCap=document.getElementById('tabcap');
  tabBtns.forEach(btn=>btn.addEventListener('click',()=>{
    if(btn.classList.contains('active'))return;
    tabBtns.forEach(b=>b.classList.remove('active')); btn.classList.add('active');
    const src=btn.dataset.src, cap=btn.dataset.cap;
    tabImg.classList.add('fade'); tabCap.style.opacity='0';
    setTimeout(()=>{
      const pre=new Image(); pre.onload=()=>{tabImg.src=src; tabImg.classList.remove('fade')}; pre.src=src;
      tabCap.textContent=cap; tabCap.style.opacity='1';
    }, reduce?0:180);
  }));

  // 3D tilt on system images (matches original product-page feel)
  if(!reduce){document.querySelectorAll('.tilt').forEach(el=>{
    el.addEventListener('mousemove',e=>{const r=el.getBoundingClientRect();
      const rx=(((e.clientY-r.top)/r.height)-.5)*-5, ry=(((e.clientX-r.left)/r.width)-.5)*5;
      el.style.transform=`perspective(1100px) rotateX(${rx}deg) rotateY(${ry}deg)`});
    el.addEventListener('mouseleave',()=>el.style.transform='');
  })}

  // steps lottie (green → violet via CSS hue-rotate) + timeline fill on scroll
  const stepsBox=document.getElementById('stepsLottie');
  if(stepsBox && window.lottie){
    try{lottie.loadAnimation({container:stepsBox,renderer:'svg',loop:true,autoplay:!reduce,path:'/product-landings/steps.json'});}catch(e){}
  }
  // scroll-scrubbed timeline: line fills with scroll, each step lights up when reached (like the service pages)
  const tl=document.getElementById('timeline2');
  if(tl){
    const fill=tl.querySelector('.tl-fill'), tlSteps=[...tl.querySelectorAll('.tl-step')];
    function tlLoop(){
      const rect=tl.getBoundingClientRect(), vh=window.innerHeight;
      let p=(0.7*vh - rect.top)/(0.1*vh + rect.height);
      p=Math.min(1,Math.max(0,p));
      if(reduce)p=1;
      fill.style.transform=`scaleY(${p})`;
      const fillPx=p*rect.height;
      tlSteps.forEach(s=>s.classList.toggle('active', fillPx >= s.offsetTop+8));
      requestAnimationFrame(tlLoop);
    }
    requestAnimationFrame(tlLoop);
  }

  // scroll-driven "unfold": screen starts laid back (60°) and rises upright (ported from ProductHeroUnfold)
  (function(){
    const stage=document.querySelector('.mock-stage'), frame=document.getElementById('mock');
    if(!stage||!frame)return;
    const START=60, clamp=(v,a,b)=>Math.min(b,Math.max(a,v));
    function loop(){
      const rect=stage.getBoundingClientRect(), vh=window.innerHeight;
      let p=clamp((vh*0.9-rect.top)/(vh*0.5),0,1); p=p*p*(3-2*p);
      const rx=reduce?0:(1-p)*START, sc=0.9+p*0.1;
      frame.style.transform=`rotateX(${rx}deg) scale(${sc})`;
      frame.style.boxShadow=`0 ${Math.round(30+(1-p)*50)}px ${Math.round(70+(1-p)*50)}px rgba(0,0,0,${(0.5+(1-p)*0.25).toFixed(2)})`;
      requestAnimationFrame(loop);
    }
    requestAnimationFrame(loop);
  })();

  // ===== interactive pricing carousel (ported from PricingCarousel) =====
  const PLANS=[
    {name:'חבילת Trio',price:'990',note:'לחודש · 3 תוכנות',desc:'בוחרים 3 תוכנות מהסוויטה במחיר אחד, חיסכון של כ-27% מול רכישה בנפרד.',target:'מי שרוצה כמה כלים',items:['3 תוכנות לבחירתכם','workspace מאוחד','חיוב אחד','מכסות הוואטסאפ מצטברות','חיסכון ~27%'],benefits:['חודש ראשון חינם','חיסכון מיידי','ניהול אחד']},
    {name:'חבילת Suite-5',price:'1,490',note:'לחודש · 5 תוכנות',popular:true,desc:'חמש תוכנות לבחירתכם, חיסכון של כ-34% מול רכישה בנפרד.',target:'עסק שרוצה עומק',items:['5 תוכנות לבחירתכם','workspace מאוחד','חיוב אחד','מכסות הוואטסאפ מצטברות','חיסכון ~34%'],benefits:['חודש ראשון חינם','הכי משתלם למרובי-כלים']},
    {name:'סוויטה מלאה',price:'2,490',note:'לחודש · כל התוכנות',desc:'כל משפחת המוצרים של HELIX תחת מנוי אחד, למי שרוצה את הכל.',target:'ארגון שרוצה את כל הערכה',items:['כל התוכנות הפעילות','workspace מאוחד','עדיפות בתמיכה','מכסות וואטסאפ מוגדלות','חיסכון 40%+'],benefits:['חודש ראשון חינם','הערך המקסימלי'],footnote:'* חיוב שנתי, חודשיים חינם על כל מסלול.'},
  ];
  const pcWrap=document.getElementById('pcWrap');
  if(pcWrap){
    const pcSide=document.getElementById('pcSide'), pcTabs=document.getElementById('pcTabs'), pcDots=document.getElementById('pcDots');
    const n=PLANS.length; let cur=1, auto;
    const posOf=(i)=>{const d=((i-cur)%n+n)%n; return d===0?'center':d===1?'left':d===n-1?'right':d===2?'far-left':d===n-2?'far-right':'hidden-card'};
    // build static shells once
    pcSide.innerHTML=PLANS.map((p,i)=>`<button class="pc-side-item" data-i="${i}">${p.name}<span class="pc-side-tag">${p.price} ₪</span></button>`).join('');
    pcTabs.innerHTML=PLANS.map((p,i)=>`<button class="pc-tab" data-i="${i}">${p.name}</button>`).join('');
    pcDots.innerHTML=PLANS.map((p,i)=>`<button class="pc-dot" data-i="${i}" aria-label="${p.name}"></button>`).join('');
    pcWrap.innerHTML=PLANS.map((p)=>`
      <div class="pc-card${p.popular?' is-popular':''}">
        ${p.popular?'<span class="pc-popular">הכי פופולרי</span>':''}
        <div class="pc-header"><span class="pc-name">${p.name}</span>
          <div><div class="pc-price">₪${p.price}</div><div class="pc-price-note">${p.note}</div></div></div>
        <p class="pc-desc">${p.desc}</p>
        <div class="pc-target">${p.target}</div>
        <ul class="pc-items">${p.items.map(it=>`<li><span class="pc-check">✓</span>${it}</li>`).join('')}</ul>
        <div class="pc-benefits">${p.benefits.map(b=>`<span class="pc-benefit">${b}</span>`).join('')}</div>
        <button class="pc-cta">התחלה חינם</button>
        ${p.footnote?`<p class="pc-footnote">${p.footnote}</p>`:''}
      </div>`).join('');
    const cards=[...pcWrap.children], sides=[...pcSide.children], tabs=[...pcTabs.children], dots=[...pcDots.children];
    function render(){
      cards.forEach((c,i)=>{c.className=`pc-card ${posOf(i)}${PLANS[i].popular?' is-popular':''}`});
      sides.forEach((s,i)=>s.classList.toggle('active',i===cur));
      tabs.forEach((s,i)=>s.classList.toggle('active',i===cur));
      dots.forEach((s,i)=>s.classList.toggle('active',i===cur));
    }
    const go=(d)=>{cur=(cur+d+n)%n;render();stop()};
    const goTo=(i)=>{cur=i;render();stop()};
    const stop=()=>{if(auto)clearInterval(auto);auto=null};
    const start=()=>{if(!reduce)auto=setInterval(()=>{cur=(cur+1)%n;render()},5500)};
    [...sides,...tabs,...dots].forEach(el=>el.addEventListener('click',()=>goTo(+el.dataset.i)));
    document.getElementById('pcPrev').addEventListener('click',()=>go(-1));
    document.getElementById('pcNext').addEventListener('click',()=>go(1));
    pcWrap.addEventListener('click',(e)=>{
      const cta=e.target.closest('.pc-cta');
      if(cta){if(typeof confetti==='function'&&!reduce){const r=cta.getBoundingClientRect();
        confetti({particleCount:90,spread:75,origin:{x:(r.left+r.width/2)/innerWidth,y:(r.top+r.height/2)/innerHeight},colors:['#A78BFA','#C4B5FD','#8B5CF6','#E9E7EF'],disableForReducedMotion:true})}return}
      if(window.innerWidth<=768)return;
      const r=pcWrap.getBoundingClientRect(); go(e.clientX-r.left < r.width/2 ? 1 : -1);
    });
    let tsx=0; pcWrap.addEventListener('touchstart',e=>tsx=e.touches[0].clientX,{passive:true});
    pcWrap.addEventListener('touchend',e=>{const d=tsx-e.changedTouches[0].clientX;if(Math.abs(d)>25)go(d>0?1:-1)});
    window.addEventListener('keydown',e=>{if(e.key==='ArrowRight')go(-1);if(e.key==='ArrowLeft')go(1)});
    render(); start();
  }

  // packages fab: appears after scroll, scrolls to the plans section
  const fabPkg=document.getElementById('fabPkg');
  if(fabPkg){
    fabPkg.addEventListener('click',()=>document.getElementById('pricing')?.scrollIntoView({behavior:'smooth'}));
    const onScroll=()=>fabPkg.classList.toggle('show', window.scrollY>400);
    window.addEventListener('scroll',onScroll,{passive:true}); onScroll();
  }
  // referral pill: appears occasionally (after 9s), dismissible, remembers dismissal for the session
  const refPill=document.getElementById('refPill'), refClose=document.getElementById('refClose');
  if(refPill && !sessionStorage.getItem('refDismissed')){
    setTimeout(()=>refPill.classList.add('show'), 9000);
    refClose?.addEventListener('click',()=>{refPill.classList.remove('show');try{sessionStorage.setItem('refDismissed','1')}catch(e){}});
  }

  // rocket lottie inside every lead form (green base → violet via CSS hue-rotate)
  document.querySelectorAll('.rocket-lottie').forEach(box=>{
    if(window.lottie){try{lottie.loadAnimation({container:box,renderer:'svg',loop:true,autoplay:!reduce,path:'/product-landings/rocket-mail.json'});}catch(e){}}
  });

  // business-email validation (block free providers) + WhatsApp prefill helpers
  const FREE_EMAIL=/@(gmail|googlemail|yahoo|ymail|hotmail|outlook|live|msn|icloud|me|mac|aol|walla|nana|proton|protonmail|gmx|mail|zoho|yandex)\.[a-z.]+$/i;
  function validBiz(form){
    const email=form.querySelector('input[type="email"]'), err=form.querySelector('.ff-error');
    if(email && FREE_EMAIL.test(email.value.trim())){if(err)err.classList.add('show');email.focus();return false;}
    if(err)err.classList.remove('show');return true;
  }
  const WA='https://wa.me/972544468883', PRODUCT='HELIX OPS';
  const waLink=(name)=>`${WA}?text=${encodeURIComponent(`שלום, מעניין אותי ${PRODUCT}${name?`. שמי ${name}`:''}`)}`;
  // default prefilled text on all static WhatsApp links (fab, offer bar, final CTA)
  document.querySelectorAll('a[href^="https://wa.me/972544468883"]').forEach(a=>{ if(a.href.indexOf('?text=')===-1) a.href=waLink(''); });
  // lead-form WhatsApp buttons: inject the visitor's name from their own form on click
  document.querySelectorAll('.lead-wa').forEach(a=>a.addEventListener('click',()=>{
    const card=a.closest('.lead-card'), nm=card&&card.querySelector('input[id$="-name"]');
    a.href=waLink(nm&&nm.value.trim());
  }));

  // lead forms inside cards: validate business email → success state
  document.querySelectorAll('.lead-card form.lead-form').forEach(f=>{
    f.addEventListener('submit',e=>{
      e.preventDefault();
      if(!f.checkValidity()){f.reportValidity();return}
      if(!validBiz(f))return;
      const card=f.closest('.lead-card'), succ=card&&card.querySelector('.lead-success');
      f.style.display='none';
      if(succ){succ.hidden=false;
        if(typeof confetti==='function'&&!reduce){const r=succ.getBoundingClientRect();
          confetti({particleCount:70,spread:70,origin:{x:(r.left+r.width/2)/innerWidth,y:(r.top+r.height/2)/innerHeight},colors:['#A78BFA','#C4B5FD','#8B5CF6','#E9E7EF'],disableForReducedMotion:true})}}
    });
  });

  // timed popup (every page, after 60s; 7-day cooldown) → opens WhatsApp with name+product+interest
  const xp=document.getElementById('xpOverlay');
  if(xp){
    const KEY='helix-popup-dismissed-at', COOL=7*24*3600*1000, DELAY=60000;
    const close=()=>{xp.classList.remove('show');try{localStorage.setItem(KEY,String(Date.now()))}catch(e){}};
    let dismissed=false; try{const at=Number(localStorage.getItem(KEY)||0); dismissed=at>0 && (Date.now()-at)<COOL;}catch(e){}
    if(!dismissed) setTimeout(()=>xp.classList.add('show'), DELAY);
    document.getElementById('xpClose').addEventListener('click',close);
    xp.addEventListener('click',e=>{if(e.target===xp)close()});
    window.addEventListener('keydown',e=>{if(e.key==='Escape'&&xp.classList.contains('show'))close()});
    const xpLead=document.getElementById('xpLead');
    xpLead.addEventListener('submit',e=>{
      e.preventDefault();
      if(!xpLead.checkValidity()){xpLead.reportValidity();return}
      if(!validBiz(xpLead))return;
      const name=document.getElementById('xp-name').value.trim(), phone=document.getElementById('xp-phone').value.trim(), interest=document.getElementById('xp-interest').value;
      const msg=`שלום, השארתי פרטים באתר\nשם: ${name}\nטלפון: ${phone}\nמעניין אותי: ${interest||PRODUCT}`;
      window.open(`${WA}?text=${encodeURIComponent(msg)}`,'_blank');
      document.getElementById('xpForm').hidden=true; document.getElementById('xpSuccess').hidden=false;
      setTimeout(close,2200);
    });
  }

  // magnetic primary CTA
  if(!reduce){document.querySelectorAll('.btn-primary').forEach(btn=>{
    btn.addEventListener('mousemove',e=>{const r=btn.getBoundingClientRect();
      btn.style.transform=`translate(${(e.clientX-r.left-r.width/2)*.15}px,${(e.clientY-r.top-r.height/2)*.25-2}px)`});
    btn.addEventListener('mouseleave',()=>btn.style.transform='');
  })}
